// ---------------------------------------------------------------- spec

export type LiveVariant = "trend" | "bollinger" | "rsi" | "levels" | "score" | "volume";

export type WidgetKind =
  | "RsiPlayground"
  | "StopLossCalculator"
  | "PositionSizer"
